"""Numerics for linear time-invariant SISO systems with numpy only: state space, matrix exponential, exact simulation, frequency response.

* :func:`expm` - scaling and squaring with a (6,6) Pade approximant (Golub and Van Loan, algorithm 11.3.1).  Accurate to about
  1e-15 relative for a matrix whose norm is moderate; for a badly scaled (non-normal) matrix the error grows with its condition.
* :func:`simulate` - exact: a step or a ramp input is generated by an augmented system whose state includes the input, so the
  discretisation is exact at the sample instants (the only error is rounding), not an approximation of the input.
* frequency response by Horner evaluation of the numerator and denominator at ``s = j w`` (continuous) or ``z = exp(j w T)``
  (discrete).

No scipy.  Nothing here imports the tool layer.
"""

from __future__ import annotations

import math
from dataclasses import dataclass
from typing import Any, Callable

import numpy as np

from eng_toolkit.domains.control import _poly as poly
from eng_toolkit.errors import ToolFailure

MAX_SAMPLES = 100_000
DIVERGENCE_LIMIT = 1e100


@dataclass(frozen=True)
class TF:
    """A SISO transfer function: descending coefficients, ``den[0] != 0``, ``dt`` the sample time (None = continuous)."""

    num: np.ndarray
    den: np.ndarray
    dt: float | None = None

    @property
    def order(self) -> int:
        return len(self.den) - 1

    @property
    def relative_degree(self) -> int:
        return len(self.den) - len(self.num)

    @property
    def proper(self) -> bool:
        return self.relative_degree >= 0

    @property
    def discrete(self) -> bool:
        return self.dt is not None


# ----------------------------------------------------------------------------------------------- matrix exponential


def expm(a: np.ndarray) -> np.ndarray:
    a = np.asarray(a, dtype=float)
    n = a.shape[0]
    if n == 0:
        return a.copy()
    norm = float(np.linalg.norm(a, np.inf))
    if not math.isfinite(norm):
        raise ToolFailure("input.out_of_range", "the system matrix is not finite", {})
    j = 0 if norm <= 0.5 else int(math.ceil(math.log2(norm))) + 1
    if j > 1000:
        raise ToolFailure("input.out_of_range", "the system matrix is too large for the matrix exponential (time scale far outside the representable range)", {})
    x = a / (2.0**j)
    q = 6
    ident = np.eye(n)
    num, den, power, c = ident.copy(), ident.copy(), ident.copy(), 1.0
    for k in range(1, q + 1):
        c = c * (q - k + 1) / ((2 * q - k + 1) * k)
        power = x @ power
        num = num + c * power
        den = den + (-1) ** k * c * power
    e = np.linalg.solve(den, num)
    for _ in range(j):
        e = e @ e
    if not np.all(np.isfinite(e)):
        raise ToolFailure("input.out_of_range", "the matrix exponential overflowed: the time step is far too large for the fastest dynamics", {})
    return e


# ----------------------------------------------------------------------------------------------- transfer function <-> state space


def tf2ss(tf: TF) -> tuple[np.ndarray, np.ndarray, np.ndarray, float]:
    """Controllable canonical form of a proper transfer function.  ``n = 0`` gives empty matrices and the gain as ``D``."""
    if not tf.proper:
        raise ToolFailure("input.invalid", "the transfer function is improper (numerator order above denominator order)", {})
    a = tf.den / tf.den[0]
    n = len(a) - 1
    b = np.concatenate([np.zeros(len(tf.den) - len(tf.num)), tf.num]) / tf.den[0]
    d = float(b[0])
    if n == 0:
        return np.zeros((0, 0)), np.zeros((0, 1)), np.zeros((1, 0)), d
    amat = np.zeros((n, n))
    amat[:-1, 1:] = np.eye(n - 1)
    amat[-1, :] = -a[1:][::-1]
    bmat = np.zeros((n, 1))
    bmat[-1, 0] = 1.0
    cvec = (b[1:] - d * a[1:])[::-1]
    return amat, bmat, cvec.reshape(1, n), d


def ss_poles(a: np.ndarray) -> np.ndarray:
    return np.linalg.eigvals(a).astype(complex) if a.shape[0] else np.array([], dtype=complex)


def ss_to_tf_polys(a: np.ndarray, b: np.ndarray, c: np.ndarray, d: float) -> tuple[np.ndarray, np.ndarray]:
    """Numerator and denominator (descending) of ``c (sI - a)^-1 b + d`` from characteristic polynomials; the numerator is
    ``det(sI - a + b c) - det(sI - a) + d det(sI - a)``.  Loses precision by cancellation for high orders."""
    n = a.shape[0]
    if n == 0:
        return np.array([d]), np.array([1.0])
    den = np.real(np.poly(a))
    num = np.real(np.poly(a - b @ c)) - den + d * den
    return poly.trim(num), den


# ----------------------------------------------------------------------------------------------- simulation


@dataclass
class Simulation:
    t: np.ndarray
    u: np.ndarray
    y: np.ndarray
    truncated: bool
    note: str = ""


def _augmented(a: np.ndarray, b: np.ndarray, kind: str) -> tuple[np.ndarray, np.ndarray, int]:
    n = a.shape[0]
    if kind == "step":
        m = np.zeros((n + 1, n + 1))
        m[:n, :n], m[:n, n:] = a, b
        s0 = np.zeros(n + 1)
        s0[n] = 1.0
        return m, s0, n
    m = np.zeros((n + 2, n + 2))
    m[:n, :n], m[:n, n : n + 1] = a, b
    m[n, n + 1] = 1.0
    s0 = np.zeros(n + 2)
    s0[n + 1] = 1.0
    return m, s0, n


def simulate(a: np.ndarray, b: np.ndarray, c: np.ndarray, d: float, *, kind: str, samples: int, step: float, discrete: bool) -> Simulation:
    """Unit step / unit impulse / unit ramp response of ``(a, b, c, d)`` at ``samples`` instants ``0, step, 2 step, ...``.

    Continuous: exact by the matrix exponential of an augmented system (``u`` is a state, so step and ramp are not approximated).
    The Dirac of an impulse acting through ``d`` is not representable and is left out (the caller warns).  Discrete: the plain
    recursion ``x+ = a x + b u``; the discrete impulse is the unit pulse at k = 0 and the ramp is ``u_k = k T``.
    Stops early (``truncated``) once a state exceeds 1e100, so no infinity can appear.
    """
    n = a.shape[0]
    t = np.arange(samples, dtype=float) * step
    if kind == "step":
        u = np.ones(samples)
    elif kind == "ramp":
        u = t.copy()
    else:
        u = np.zeros(samples)
        if discrete:
            u[0] = 1.0
    if n == 0:
        y = d * u
        return Simulation(t, u, y, False)
    xs = np.empty((samples, n))
    truncated = False
    if discrete:
        x = np.zeros(n)
        bcol = b[:, 0]
        for k in range(samples):
            xs[k] = x
            if not np.abs(x).max() < DIVERGENCE_LIMIT:
                truncated = True
                samples = k
                break
            x = a @ x + bcol * u[k]
        if truncated:
            xs, t, u = xs[:samples], t[:samples], u[:samples]
    elif kind == "impulse":
        md = expm(a * step)
        x = b[:, 0].copy()
        for k in range(samples):
            xs[k] = x
            if not np.abs(x).max() < DIVERGENCE_LIMIT:
                truncated = True
                samples = k
                break
            x = md @ x
        if truncated:
            xs, t, u = xs[:samples], t[:samples], u[:samples]
    else:
        m, s, _ = _augmented(a, b, kind)
        md = expm(m * step)
        for k in range(samples):
            xs[k] = s[:n]
            if not np.abs(s).max() < DIVERGENCE_LIMIT:
                truncated = True
                samples = k
                break
            s = md @ s
        if truncated:
            xs, t, u = xs[:samples], t[:samples], u[:samples]
    y = xs @ c[0] + d * u
    return Simulation(t, u, y, truncated)


# ----------------------------------------------------------------------------------------------- time grid


def time_grid(poles: np.ndarray, *, discrete: bool, step: float | None, t_final: float | None, samples: int | None) -> tuple[int, float, list[str]]:
    """Choose ``(number of samples, sample step, notes)`` from the slowest and fastest poles unless the caller fixed them.

    Continuous: the end time is ten times the slowest decay time constant 1/sigma (or ten times the slowest non-zero
    pole magnitude for an unstable or marginal system, ten seconds if every pole is at the origin); the step resolves the
    fastest pole at ten samples per time constant, with 2001 samples at least and 100000 at most.  Discrete: the step is the
    sample time and the number of samples follows from the slowest pole radius.
    """
    notes: list[str] = []
    if discrete:
        assert step is not None
        radii = np.abs(poles)
        if t_final is not None:
            k_end = int(math.ceil(t_final / step - 1e-9))
        elif poles.size == 0:
            k_end = 20
        elif np.all(radii < 1.0 - 1e-9):
            slowest = float(radii.max())
            k_end = max(20, int(math.ceil(10.0 / -math.log(slowest)))) if slowest > 0 else 20
        else:
            k_end = 200
            notes.append("the system is not asymptotically stable: 200 samples are shown by default (give 't_final' for another length)")
        return (samples if samples is not None else k_end + 1), step, notes
    mags = np.abs(poles)
    nonzero = mags[mags > 0]
    if t_final is not None:
        t_end = t_final
    elif nonzero.size == 0:
        t_end = 10.0
        notes.append("no time scale in the poles (none, or all at the origin): 10 s is shown by default; give 't_final' for another length")
    else:
        decay = [-p.real for p in poles if abs(p) > 0 and p.real < -1e-9 * abs(p)]
        t_end = 10.0 / min(decay) if len(decay) == nonzero.size else 10.0 / float(nonzero.min())
    fast = float(mags.max()) if poles.size else 0.0
    n_samples = samples if samples is not None else int(min(MAX_SAMPLES, max(2001, math.ceil(t_end * fast * 10.0) + 1)))
    return n_samples, t_end / (n_samples - 1), notes


# ----------------------------------------------------------------------------------------------- step response metrics


def _crossing(t: np.ndarray, y: np.ndarray, level: float, start: int = 0) -> float | None:
    """First time at or after index ``start`` at which ``y`` goes from below ``level`` to at-or-above it (linear interpolation)."""
    for i in range(max(start, 1), len(y)):
        if y[i - 1] < level <= y[i]:
            frac = (level - y[i - 1]) / (y[i] - y[i - 1])
            return float(t[i - 1] + frac * (t[i] - t[i - 1]))
    return None


def step_metrics(t: np.ndarray, y: np.ndarray, y_ss: float, tol: float) -> dict[str, Any]:
    """Rise time (10 to 90 % of the final value), peak, percent overshoot and settling time of a step response.

    ``y_ss`` is the final value the response is judged against (the DC gain for a stable system).  Times are by linear
    interpolation between samples, the peak by a parabola through the three samples around the maximum.  A quantity that does
    not exist (the response never reaches 90 %, or never stays inside the band within the window) is ``None`` with a reason.
    """
    out: dict[str, Any] = {}
    sign = 1.0 if y_ss >= 0 else -1.0
    z = y * sign
    ref = abs(y_ss)
    i_pk = int(np.argmax(z))
    peak_t, peak_v = float(t[i_pk]), float(z[i_pk])
    if 0 < i_pk < len(z) - 1:
        y0, y1, y2 = z[i_pk - 1], z[i_pk], z[i_pk + 1]
        denom = y0 - 2 * y1 + y2
        if denom != 0:
            shift = 0.5 * (y0 - y2) / denom
            if abs(shift) <= 1:
                dt = t[i_pk] - t[i_pk - 1]
                peak_t = float(t[i_pk] + shift * dt)
                peak_v = float(y1 - 0.25 * (y0 - y2) * shift)
    out["peak_value"] = peak_v * sign
    out["peak_time"] = peak_t
    if ref == 0.0:
        out.update(overshoot_percent=None, rise_time=None, settling_time=None, reason="the final value is zero, so overshoot, rise time and settling band are undefined")
        return out
    out["overshoot_percent"] = max(0.0, 100.0 * (peak_v - ref) / ref)
    t10 = _crossing(t, z, 0.1 * ref)
    t90 = _crossing(t, z, 0.9 * ref, start=0)
    out["rise_time"] = (t90 - t10) if (t10 is not None and t90 is not None) else None
    outside = np.nonzero(np.abs(z - ref) > tol * ref)[0]
    if outside.size == 0:
        out["settling_time"] = 0.0
    elif outside[-1] >= len(z) - 1:
        out["settling_time"] = None
        out["settling_reason"] = "the response is still outside the band at the end of the window"
    else:
        i = int(outside[-1])
        # the last exit from the band: interpolate where |z - ref| crosses tol*ref between sample i and i+1
        e0, e1 = abs(z[i] - ref) - tol * ref, abs(z[i + 1] - ref) - tol * ref
        frac = e0 / (e0 - e1) if e0 != e1 else 1.0
        out["settling_time"] = float(t[i] + frac * (t[i + 1] - t[i]))
    return out


# ----------------------------------------------------------------------------------------------- frequency response


def tf_values(tf: TF, w: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    """Numerator and denominator values at ``s = j w`` (continuous) or ``z = exp(j w T)`` (discrete)."""
    x = 1j * w if tf.dt is None else np.exp(1j * w * tf.dt)
    return poly.polyval(tf.num, x), poly.polyval(tf.den, x)


def tf_eval(tf: TF, w: np.ndarray) -> np.ndarray:
    n, d = tf_values(tf, w)
    tiny = np.where(np.abs(d) < 1e-300, 1e-300, d)
    out = n / tiny
    return np.where(np.isfinite(out), out, 1e300 + 0j)


def magnitude_db(n: np.ndarray, d: np.ndarray) -> np.ndarray:
    return 20.0 * (np.log10(np.maximum(np.abs(n), 1e-300)) - np.log10(np.maximum(np.abs(d), 1e-300)))


def low_frequency_phase(tf: TF) -> float:
    """Phase (radians) of the transfer function as the frequency goes to zero, including the integrators (-90 degrees each)."""
    if tf.dt is None:
        kn, cn = poly.lowest_order(tf.num)
        kd, cd = poly.lowest_order(tf.den)
        sign = 0.0 if cn / cd > 0 else math.pi
        return sign + (kn - kd) * math.pi / 2.0
    kn = poly.multiplicity_at(tf.num, 1.0)
    kd = poly.multiplicity_at(tf.den, 1.0)
    defl_n, defl_d = tf.num.astype(float), tf.den.astype(float)
    for _ in range(kn):
        defl_n = _deflate(defl_n, 1.0)
    for _ in range(kd):
        defl_d = _deflate(defl_d, 1.0)
    value = float(np.sum(defl_n)) / float(np.sum(defl_d))
    return (0.0 if value > 0 else math.pi) + (kn - kd) * math.pi / 2.0


def _deflate(p: np.ndarray, root: float) -> np.ndarray:
    out = [p[0]]
    for c in p[1:-1]:
        out.append(out[-1] * root + c)
    return np.array(out)


def phase_degrees(tf: TF, w: np.ndarray) -> np.ndarray:
    """Unwrapped phase in degrees: numerator and denominator unwrapped separately, then anchored at the low-frequency asymptote."""
    n, d = tf_values(tf, w)
    phase = np.unwrap(np.angle(n)) - np.unwrap(np.angle(d))
    asym = low_frequency_phase(tf)
    phase = phase + 2.0 * math.pi * round((asym - phase[0]) / (2.0 * math.pi))
    return np.degrees(phase)


def log_grid(lo: float, hi: float, points: int) -> np.ndarray:
    return np.logspace(math.log10(lo), math.log10(hi), points)


def bisect_log(fn: Callable[[float], float], a: float, b: float, iterations: int = 100) -> float:
    """Root of ``fn`` between ``a`` and ``b`` (a sign change) by bisection on log w."""
    la, lb = math.log(a), math.log(b)
    fa = fn(a)
    for _ in range(iterations):
        lm = 0.5 * (la + lb)
        m = math.exp(lm)
        fm = fn(m)
        if (fm > 0) == (fa > 0):
            la, fa = lm, fm
        else:
            lb = lm
    return math.exp(0.5 * (la + lb))


def margins(evaluate: Callable[[np.ndarray], np.ndarray], w: np.ndarray) -> dict[str, Any]:
    """Gain and phase crossovers of a loop transfer function ``evaluate(w) -> L(j w)`` scanned on the grid ``w``.

    Gain crossovers: ``|L| = 1``; phase margin = 180 + angle(L) wrapped to (-180, 180].  Phase crossovers: ``Im L = 0`` with
    ``Re L < 0``; gain margin = 1 / |L|.  Every crossing is refined by bisection on the direct evaluation.  Crossings closer
    together than one grid cell can be missed; the grid used by the tools is 4000 points.
    """
    values = evaluate(w)

    def scalar(x: float) -> complex:
        return complex(evaluate(np.array([x]))[0])

    log_mag = np.log(np.maximum(np.abs(values), 1e-300))
    gain_cross: list[dict[str, float]] = []
    for i in np.nonzero(np.signbit(log_mag[:-1]) != np.signbit(log_mag[1:]))[0]:
        wc = bisect_log(lambda x: math.log(max(abs(scalar(x)), 1e-300)), float(w[i]), float(w[i + 1]))
        v = scalar(wc)
        if abs(v) > 1e100 or abs(v) < 1e-100:
            continue
        pm = (180.0 + math.degrees(math.atan2(v.imag, v.real)) + 180.0) % 360.0 - 180.0
        if pm == -180.0:
            pm = 180.0
        gain_cross.append({"frequency": wc, "phase_margin_deg": pm})
    imag = values.imag
    phase_cross: list[dict[str, float]] = []
    for i in np.nonzero(np.signbit(imag[:-1]) != np.signbit(imag[1:]))[0]:
        wc = bisect_log(lambda x: scalar(x).imag, float(w[i]), float(w[i + 1]))
        v = scalar(wc)
        if abs(v) > 1e12 or abs(v) < 1e-12 or v.real >= 0:
            continue
        phase_cross.append({"frequency": wc, "magnitude": abs(v), "gain_margin": 1.0 / abs(v), "gain_margin_db": -20.0 * math.log10(abs(v))})
    return {"gain_crossovers": gain_cross, "phase_crossovers": phase_cross}


def peak_magnitude(evaluate: Callable[[np.ndarray], np.ndarray], w: np.ndarray) -> dict[str, Any]:
    """Maximum of ``|evaluate(w)|`` over the grid, refined by golden-section search between the neighbours of the grid maximum.

    ``at_edge`` is True when the maximum is at the first or last grid point (the true peak may lie outside the grid).
    """
    mags = np.abs(evaluate(w))
    i = int(np.argmax(mags))
    if i in (0, len(w) - 1):
        return {"magnitude": float(mags[i]), "frequency": float(w[i]), "at_edge": True}

    def f(x: float) -> float:
        return float(abs(evaluate(np.array([x]))[0]))

    lo, hi = math.log(w[i - 1]), math.log(w[i + 1])
    ratio = (math.sqrt(5.0) - 1.0) / 2.0
    c, d = hi - ratio * (hi - lo), lo + ratio * (hi - lo)
    fc, fd = f(math.exp(c)), f(math.exp(d))
    for _ in range(80):
        if fc > fd:
            hi, d, fd = d, c, fc
            c = hi - ratio * (hi - lo)
            fc = f(math.exp(c))
        else:
            lo, c, fc = c, d, fd
            d = lo + ratio * (hi - lo)
            fd = f(math.exp(d))
    x = math.exp(0.5 * (lo + hi))
    best = max(f(x), float(mags[i]))
    return {"magnitude": best, "frequency": x if best != float(mags[i]) else float(w[i]), "at_edge": False}


# ----------------------------------------------------------------------------------------------- delay


def pade_delay(delay: float, order: int) -> tuple[np.ndarray, np.ndarray]:
    """Numerator and denominator (descending) of the (n, n) Pade approximation of ``exp(-delay s)``.

    ``exp(-x) ~ P(-x)/P(x)`` with ``P(x) = sum_k (2n-k)! n! / ((2n)! k! (n-k)!) x^k``.
    """
    n = order
    coef = [math.factorial(2 * n - k) * math.factorial(n) / (math.factorial(2 * n) * math.factorial(k) * math.factorial(n - k)) for k in range(n + 1)]
    den = np.array([coef[k] * delay**k for k in range(n, -1, -1)])
    num = np.array([coef[k] * (-delay) ** k for k in range(n, -1, -1)])
    return num, den


__all__ = [
    "DIVERGENCE_LIMIT", "MAX_SAMPLES", "Simulation", "TF", "bisect_log", "expm", "log_grid", "low_frequency_phase", "magnitude_db", "margins",
    "pade_delay", "peak_magnitude", "phase_degrees", "simulate", "ss_poles", "ss_to_tf_polys", "step_metrics", "tf2ss", "tf_eval", "tf_values", "time_grid",
]
